//! What this backend's own pipeline does with a stream of coded frames.
//!
//! The fixture is synthetic: videotestsrc through openh264enc, 640x360, 48 coded
//! pictures, generated by `tools/make-fixtures.sh` and checked by it. Synthetic is the
//! point. It carries no captured screen, and every picture in it is one the encoder is
//! known to have produced, so a pipeline that decodes fewer than 48 lost one rather than
//! being handed a stream with an ambiguous frame count.
//!
//! The count is what is asserted, because a picture cannot be: one decoded frame is
//! [FRAME_BYTES] bytes of I420, and a pipeline that loses one shows a partly decoded
//! screen.

use std::io::{Read, Write};

use rust_airplay::VideoCodec;
use rust_airplay_gstream::testing;

/// The frames of the stream, as one Annex-B stream.
///
/// The parameter sets are in front of the first slice, which is what a session's first
/// buffer holds as well: nothing needs to be prepended to this before a decoder sees it.
const DUMP: &[u8] = include_bytes!("fixtures/mirror-first-frames.h264");

/// The bytes of one decoded frame of this stream, in I420 at 640x360.
const FRAME_BYTES: usize = 640 * 360 * 3 / 2;

/// The start code every unit of an Annex-B stream is behind.
const START_CODE: [u8; 4] = [0, 0, 0, 1];

/// The program to run pipelines in, if this machine has one.
fn launcher() -> Option<String> {
    match testing::launcher() {
        Ok(program) => Some(program),
        Err(error) => {
            eprintln!("skipping: {error}");
            None
        }
    }
}

/// How many pictures the fixture holds.
///
/// Not the number of units: a slice is a picture, but the parameter sets and the access
/// unit delimiters around it are units too, and counting those as pictures is how this
/// test once reported a pipeline that lost frames when it had lost none. openh264enc
/// writes an access unit delimiter before every picture, so the fixture has twice as
/// many units as pictures.
fn frames_in_fixture() -> usize {
    let mut frames = 0;
    let mut at = 0;
    while at + 4 <= DUMP.len() {
        if DUMP[at..at + 4] == START_CODE {
            // The unit behind the start code: a coded slice is a picture, an access
            // unit delimiter and a parameter set are not.
            let unit = DUMP.get(at + 4).map_or(0, |byte| byte & 0x1f);
            if unit == 1 || unit == 5 {
                frames += 1;
            }
            at += 4;
        } else {
            at += 1;
        }
    }
    frames
}

/// Runs a pipeline over the fixture and returns how many decoded frames came out.
///
/// Frames are written to the pipeline's standard input and its standard output is the
/// raw decoded stream, so the count is the pipeline's own answer and not a receiver's.
fn decode_with(program: &str, pipeline: &str) -> usize {
    let mut child = std::process::Command::new(program)
        .arg("-q")
        // Handed over the way the backend hands it: as separate arguments, because a
        // caps filter holds commas and one argument holding a whole pipeline is the
        // form Windows quoting breaks.
        .args(pipeline.split_whitespace())
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .expect("a pipeline");
    let mut input = child.stdin.take().expect("a pipe to write frames to");
    let writer = std::thread::spawn(move || {
        let _ = input.write_all(DUMP);
        // Dropping the pipe is the end of stream, which is how a sink knows to play
        // what it has left before it exits.
    });
    let mut decoded = Vec::new();
    child
        .stdout
        .take()
        .expect("the pipeline's output")
        .read_to_end(&mut decoded)
        .expect("the decoded frames");
    writer.join().expect("the writer");
    let outcome = child.wait_with_output().expect("the pipeline ended");
    let said = String::from_utf8_lossy(&outcome.stderr);
    assert!(
        outcome.status.success(),
        "the pipeline failed after {} decoded bytes: {said}",
        decoded.len()
    );
    decoded.len() / FRAME_BYTES
}

#[test]
#[ignore = "needs a GStreamer runtime; see README.md"]
fn the_pipeline_this_backend_builds_decodes_every_frame() {
    let Some(program) = launcher() else {
        return;
    };
    // The arguments the renderer builds for a video stream, with its sink replaced by
    // the decoded bytes so that what it produced can be measured. This is the path a
    // session takes: fdsrc, the parser and decoder the options chose, and nothing else.
    let path = std::env::temp_dir().join(format!("airplay-gst-decode-{}.raw", std::process::id()));
    let _ = std::fs::remove_file(&path);
    let location = path.display().to_string().replace('\\', "/");
    let sink = format!("filesink location={location}");
    let args =
        testing::video_args(VideoCodec::H264, &sink).expect("the arguments of a video pipeline");
    println!("pipeline: {}", args.join(" "));
    if let Err(error) = testing::feed(&program, &args, DUMP) {
        let _ = std::fs::remove_file(&path);
        panic!("the pipeline a video stream runs failed: {error}");
    }
    let decoded = std::fs::metadata(&path).map(|meta| meta.len()).unwrap_or(0);
    let _ = std::fs::remove_file(&path);
    let frames = decoded as usize / FRAME_BYTES;
    let expected = frames_in_fixture();
    println!("{frames} frames decoded, fixture holds {expected}");
    assert_eq!(
        expected, 48,
        "the fixture no longer holds the 48 pictures tools/make-fixtures.sh builds"
    );
    assert!(
        frames > 0,
        "the pipeline decoded nothing from {} bytes",
        DUMP.len()
    );
    // The last picture may still be inside the decoder when the stream ends, so one
    // fewer is expected and two fewer is a lost frame.
    assert!(
        frames + 1 >= expected && frames <= expected,
        "the pipeline decoded {frames} of {expected} pictures: {} were lost",
        expected - frames
    );
}

#[test]
#[ignore = "needs a GStreamer runtime; see README.md"]
fn the_decoder_a_player_would_pick_decodes_the_same() {
    // The control. If this and the pipeline above disagree, the difference is which
    // decoder each one chose, and that is the thing worth knowing.
    let Some(program) = launcher() else {
        return;
    };
    let pipeline = "fdsrc ! decodebin ! videoconvert ! video/x-raw,format=I420 ! fdsink";
    let frames = decode_with(&program, pipeline);
    println!(
        "decodebin: {frames} frames, fixture holds {}",
        frames_in_fixture()
    );
    assert!(frames > 0, "the control pipeline decoded nothing");
    assert!(
        frames + 1 >= frames_in_fixture(),
        "decodebin decoded {frames} of {}",
        frames_in_fixture()
    );
}
